package com.cpf.batch.control.deploy; import com.cpf.batch.api.ArtifactManifest; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Service;
@Service public class CompatibilityService { private final JdbcTemplate jdbc;public CompatibilityService(JdbcTemplate j){jdbc=j;} public Result evaluate(ArtifactManifest a,String env){for(var r:jdbc.queryForList("SELECT required_capability FROM bat_version_compatibility WHERE environment_id IN (?, '*') AND (provider_coordinate=? OR provider_coordinate='*') AND enabled_yn='Y'",env,a.coordinate())){String c=String.valueOf(r.getOrDefault("required_capability",""));if(!c.isBlank()&&!a.requiredCapabilities().contains(c))return new Result(false,"MISSING_CAPABILITY:"+c);}return new Result(true,"COMPATIBLE");} public record Result(boolean allowed,String reason){} }
